raw:
{
  "spells": [
    {
      "id": "spell_water_04",
      "theory": "引水术把魔力铺进已存在的沟渠底部，像给水流让出一条低阻通道，水便沿渠向前。它只能推动现有的水，不能凭空造水，也不能把水送上高于渠口的坡。沟底若是松沙或裂缝，魔力会先漏进土里，水反而滞在原地；石砌渠和夯土渠最易疏导。",
      "casting": "手掌朝下悬在渠面上方，沿水流方向缓慢平移，让魔力贴着渠底铺开；另一手可指向前方确认沟沿走向。",
      "failure": "魔力从渠底裂缝漏散时，水面只起细碎波纹而不再前进，渠尾依旧干着。若沟沿有缺口，水会从侧面漫出，泡软旁边的小路。",
      "counters": [
        "在渠底横铺一层碎石或粗沙，魔力难以沿底连续传导。",
        "在渠中设一道略高的木板，水被挡住，魔力无法越过板顶。"
      ],
      "socialConsequences": "河谷里共用沟渠的农户欢迎这种帮助，但谁先引水、引多久常由乡约当面议定，下游人家若发现自家田口断流会立刻找上游理论。石渠的维护者担心魔力反复冲刷会让旧缝变宽，要求施术者事后帮忙补缝。城里公会记录这类施术用于菜园和工坊蓄水，若把渠水引向他人院墙或货栈地基，则会被视为损害他人财物。",
      "law": {
        "river": "consent",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初学时水只能缓慢挪动，渠尾要等很久才见湿痕。",
        "稍熟后能沿直渠把水推到预定田口，不再中途停住。",
        "熟练者能避开渠底裂缝，让水绕过松软处继续前行。",
        "更高熟练度可让水流平稳贴底，仍不能越过渠口高度。"
      ]
    },
    {
      "id": "spell_water_05",
      "theory": "止漏膜把魔力压进容器裂缝两侧，使水在缝隙表面形成一层贴合的薄障。它只封住已经找到的漏口，不加固容器本身，也不改变水的压力。陶罐、木桶和皮囊都能承载，但缝口若宽于指节，膜面会先鼓出再被水压撕开。",
      "casting": "用指尖沿漏口外缘画一圈短弧，同时把魔力从弧线两端向缝心挤压，直到渗水变成缓慢的潮意。",
      "failure": "缝口没清干净时，膜面会鼓起小泡，几息后从一侧裂开，水重新喷出。若容器壁太薄，魔力会透到内壁，反而让外侧看不出漏水，内里却慢慢渗湿。",
      "counters": [
        "用尖针从膜面边缘挑开一道小口，整层膜会顺缝脱落。",
        "把容器浸入冷水中使壁面收缩，膜与缝口错位后便失去贴合。"
      ],
      "socialConsequences": "河谷挑水人常请人临时封桶，但乡约会提醒这只撑到换箍或换板，不能当作长久修补。城中公会要求收费施术者登记漏口位置，免得货主以为容器已彻底修好而装载重物。港口搬运工欢迎皮囊止漏，船主却担心有人用薄障掩盖裂口，把带伤货桶运上船，因此常要求当场倒水验看。",
      "law": {
        "river": "consent",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初学时常留下细缝，水仍会慢慢渗出，需反复补画。",
        "熟悉后能封住指节宽的裂口，但压力稍大仍会鼓膜。",
        "熟练者能沿弯曲缝口贴膜，使桶侧不再滴水。",
        "更高熟练度可让膜面更匀，仍不能超过容器本身的耐压。"
      ]
    },
    {
      "id": "spell_water_06",
      "theory": "清渠术把魔力送入沟底淤泥，使泥粒之间的水膜松开，泥便从硬结状态变成松软的稠浆。它只负责把泥从渠底剥离，不会把泥送出沟外；若无人随后运走，泥浆会顺水流到下游重新沉积，甚至堵住更窄的渠段。",
      "casting": "以掌根按住渠底泥面，沿沟向缓缓推出一段，再抬手让魔力顺泥层散开；可配合短木耙把松泥拢到渠边。",
      "failure": "魔力散得太快时，泥面只浮起一层浑水，底下仍旧硬结，铁锹插下去仍要费力。若推得过猛，整块淤泥会翻起堵住渠口，使上游水位升高。",
      "counters": [
        "在渠底先铺一层粗砾，泥粒无法整体松离，术效大减。",
        "往沟中放活水冲刷，松开的泥会被提前带向下游，难以拢住。"
      ],
      "socialConsequences": "河谷清渠多由几户合力，乡约见证谁出工、谁运泥，清出的肥泥常按田亩分走，因此施术者不能私自把泥堆在别家地头。城中公会许可这类作业用于排水沟和工坊水道，但要求把泥运到指定堆场，否则视为堵塞公共水路。港口清淤须港务批准，船主关心的是航道深度，若泥被推到泊位附近，会被追究影响停靠。",
      "law": {
        "river": "consent",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "初学时只能松开表层稀泥，深处仍要人力挖掘。",
        "稍熟后能把一段沟底的泥整层松起，便于木耙拢走。",
        "熟练者能控制松泥范围，不让泥浆涌向邻近田口。",
        "更高熟练度可使泥浆更匀，仍须有人运走才能清空沟底。"
      ]
    }
  ]
}
